function Select<T>({ options, value, onChange, getLabel, getKey }: SelectProps<T>) {
  return (
    <ul>
      {options.map(opt => (
        <li key={getKey(opt)} onClick={() => onChange(opt)}
          style={{ fontWeight: opt === value ? 'bold' : 'normal' }}>
          {getLabel(opt)}
        </li>
      ))}
    </ul>
  );
}

// Usage — TypeScript infers T = User:
